                <button id="behavior-reset-profile-btn" style="padding:6px 10px; border:none; background:#c23b3b; color:#fff; border-radius:6px; cursor:pointer;">\u30C1\u30E3\u30FC\u30C8\u521D\u671F\u5316</button>
